CREATE TABLE "finance_readiness_evidence_versions" (
	"evidence_id" varchar(160) NOT NULL,
	"evidence_version" numeric(38, 0) NOT NULL,
	"requirement_code" text NOT NULL,
	"environment" text,
	"transaction_category" text,
	"scope_key" varchar(240) NOT NULL,
	"is_current" boolean DEFAULT true NOT NULL,
	"status" text NOT NULL,
	"effective_at" timestamp with time zone NOT NULL,
	"expires_at" timestamp with time zone,
	"safe_digest" varchar(71) NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "finance_readiness_evidence_versions_pk" PRIMARY KEY("evidence_id","evidence_version"),
	CONSTRAINT "finance_readiness_evidence_identifier_check" CHECK (length(trim("finance_readiness_evidence_versions"."evidence_id")) between 1 and 160
        and "finance_readiness_evidence_versions"."evidence_id" = trim("finance_readiness_evidence_versions"."evidence_id")
        and "finance_readiness_evidence_versions"."evidence_id" !~ '[[:cntrl:]]'
        and length(trim("finance_readiness_evidence_versions"."scope_key")) between 1 and 240
        and "finance_readiness_evidence_versions"."scope_key" = trim("finance_readiness_evidence_versions"."scope_key")
        and "finance_readiness_evidence_versions"."scope_key" !~ '[[:cntrl:]]'
        and "finance_readiness_evidence_versions"."evidence_version" >= 1),
	CONSTRAINT "finance_readiness_evidence_requirement_check" CHECK ("finance_readiness_evidence_versions"."requirement_code" in ('legal_accounting_client_purchase', 'legal_accounting_platform_subscription', 'commercial_tariff', 'capability_enforcement', 'billing_operations_policy', 'risk_policy', 'product_fulfillment', 'refund_chargeback_principal_policy', 'arc_pay_environment', 'finance_step_up', 'payout_recipient_policy', 'bank_liquidity_policy')
        and "finance_readiness_evidence_versions"."status" in ('active', 'revoked')),
	CONSTRAINT "finance_readiness_evidence_scope_check" CHECK ("finance_readiness_evidence_versions"."scope_key" = "finance_readiness_evidence_versions"."requirement_code" || ':' || coalesce("finance_readiness_evidence_versions"."environment", 'global') || ':' || coalesce("finance_readiness_evidence_versions"."transaction_category", 'global')
        and (
          ("finance_readiness_evidence_versions"."requirement_code" = 'arc_pay_environment'
            and "finance_readiness_evidence_versions"."environment" in ('sandbox', 'live')
            and "finance_readiness_evidence_versions"."transaction_category" is null)
          or ("finance_readiness_evidence_versions"."requirement_code" in ('legal_accounting_client_purchase', 'legal_accounting_platform_subscription')
            and "finance_readiness_evidence_versions"."environment" is null
            and "finance_readiness_evidence_versions"."transaction_category" in ('client_purchase', 'platform_subscription'))
          or ("finance_readiness_evidence_versions"."requirement_code" not in ('arc_pay_environment', 'legal_accounting_client_purchase', 'legal_accounting_platform_subscription')
            and "finance_readiness_evidence_versions"."environment" is null
            and "finance_readiness_evidence_versions"."transaction_category" is null)
        )),
	CONSTRAINT "finance_readiness_evidence_effective_window_check" CHECK ("finance_readiness_evidence_versions"."expires_at" is null or "finance_readiness_evidence_versions"."expires_at" > "finance_readiness_evidence_versions"."effective_at"),
	CONSTRAINT "finance_readiness_evidence_digest_check" CHECK ("finance_readiness_evidence_versions"."safe_digest" ~ '^sha256:[a-f0-9]{64}$')
);
